sources.src/InvoiceExporter.ets:
export class InvoiceExporter {
  exportInvoice(context: UIContext): string {
    const directory = context.filesDir
    return directory + '/invoice.json'
  }
}

sources.src/PaletteParser.ets:
export class PaletteParser {
  parseColor(value: string): number {
    const digits = value.replace('#', '')
    return Number.parseInt(digits, 16)
  }
}

sources.src/RuntimeLogger.ets:
export class RuntimeLogger {
  report(message: string): void {
    console.error(message)
  }
}
